import{_ as s,C as i,c as l,o as g,a3 as a,G as n,j as t,a as o}from"./chunks/framework.Dokpd4od.js";const b=JSON.parse('{"title":"Add an employee","description":"","frontmatter":{},"headers":[],"relativePath":"master/human-resources/employees/employees/add-employee.md","filePath":"master/human-resources/employees/employees/add-employee.md","lastUpdated":1793074831000}'),m={name:"master/human-resources/employees/employees/add-employee.md"};function h(d,e,p,c,u,f){const r=i("ImagePopup");return g(),l("div",null,[e[0]||(e[0]=a('<h1 id="add-an-employee" tabindex="-1">Add an employee <a class="header-anchor" href="#add-an-employee" aria-label="Permalink to &quot;Add an employee&quot;">​</a></h1><p>Adding an employee creates the record that every other HR task depends on. You enter the person&#39;s name and job, then optionally fill work, private and settings details. You can save with only a name and complete the rest later.</p><blockquote><p><strong>In simple words:</strong> Fill in who the person is and where they fit in the company, then save.</p></blockquote><p>Open <code>Employees → Employees → New Employee</code>.</p><div class="info custom-block"><p class="custom-block-title">Prerequisite</p><p>The lists on this form come from other pages. Create a <a href="./../departments/departments.html">department</a>, a <a href="./../setup/job-positions.html">job position</a>, <a href="./../setup/tags.html">tags</a> and a <a href="./../setup/work-locations.html">work location</a> first if you need new ones. Skills are added after saving. See <a href="./skills-and-resume.html">Skills and resume</a>.</p></div><p>Only <strong>Name</strong> is required. Every other field is optional. Fields do not fill each other. For example, choosing a <strong>Department</strong> does not fill <strong>Manager</strong>, <strong>Coach</strong> or <strong>Job Position</strong>.</p><h2 id="the-top-block" tabindex="-1">The top block <a class="header-anchor" href="#the-top-block" aria-label="Permalink to &quot;The top block&quot;">​</a></h2><p>The top block stays visible above all tabs.</p><ul><li><strong><em>Name:</em></strong> Required. Type the full name.</li><li><strong><em>Job Title:</em></strong> The title shown on cards and the profile.</li><li><strong>Avatar:</strong> Click <strong>Browse</strong> or drag an image into the round frame.</li><li><strong><em>Work Email:</em></strong> The business email. The envelope button opens your mail app.</li><li><strong><em>Department:</em></strong> Pick one. Click the plus button to create a department without leaving the form.</li><li><strong><em>Work Mobile:</em></strong> The business mobile number.</li><li><strong><em>Job Position:</em></strong> Pick one. The plus button creates a new position.</li><li><strong><em>Work Phone:</em></strong> The desk or office number.</li><li><strong><em>Manager:</em></strong> The person this employee reports to.</li><li><strong><em>Employee Tags:</em></strong> Pick several tags. The plus button creates a tag.</li><li><strong><em>Coach:</em></strong> A person who guides the employee, often during the first months.</li></ul><div class="info custom-block"><p class="custom-block-title">Who is who</p><table tabindex="0"><thead><tr><th>Field</th><th>Who it is</th></tr></thead><tbody><tr><td><strong>Manager</strong></td><td>The employee this person reports to.</td></tr><tr><td><strong>Coach</strong></td><td>An employee who guides this person.</td></tr><tr><td><strong>Time Off</strong> (approver)</td><td>The user who approves leave in the Time Off app.</td></tr><tr><td><strong>Attendance Manager</strong></td><td>The user who manages attendance records.</td></tr><tr><td><strong>Related User</strong></td><td>The login of this person.</td></tr></tbody></table></div><h2 id="tab-work-information" tabindex="-1">Tab: Work Information <a class="header-anchor" href="#tab-work-information" aria-label="Permalink to &quot;Tab: Work Information&quot;">​</a></h2><h3 id="location" tabindex="-1">Location <a class="header-anchor" href="#location" aria-label="Permalink to &quot;Location&quot;">​</a></h3><ul><li><strong><em>Work Address:</em></strong> A contact that holds the office address.</li><li><strong><em>Work Location:</em></strong> Where the person sits, such as <strong>Building 1, Second Floor</strong>, <strong>Home</strong> or <strong>Other</strong>.</li></ul><h3 id="approver" tabindex="-1">Approver <a class="header-anchor" href="#approver" aria-label="Permalink to &quot;Approver&quot;">​</a></h3><ul><li><strong><em>Time Off:</em></strong> The user who approves this employee&#39;s leave requests. The list shows users, such as <strong>HR Admin</strong>, not employees.</li><li><strong><em>Attendance Manager:</em></strong> The user who manages this employee&#39;s attendance.</li></ul><h3 id="schedule" tabindex="-1">Schedule <a class="header-anchor" href="#schedule" aria-label="Permalink to &quot;Schedule&quot;">​</a></h3><ul><li><strong><em>Working Hours:</em></strong> The working schedule. It is empty on a new employee and stays empty until you pick one.</li><li><strong><em>Time Zone:</em></strong> Starts as <strong>UTC</strong>. Change it to the place where the person works.</li></ul><h3 id="organization-details" tabindex="-1">Organization Details <a class="header-anchor" href="#organization-details" aria-label="Permalink to &quot;Organization Details&quot;">​</a></h3><ul><li><strong><em>Company:</em></strong> Defaults to <strong>My Company</strong>. If you change it, <strong>Job Position</strong>, <strong>Work Location</strong> and <strong>Department</strong> clear. Pick them again.</li><li><strong><em>Color:</em></strong> A colour for this employee.</li></ul><h2 id="tab-private-information" tabindex="-1">Tab: Private Information <a class="header-anchor" href="#tab-private-information" aria-label="Permalink to &quot;Tab: Private Information&quot;">​</a></h2><h3 id="private-contact" tabindex="-1">Private Contact <a class="header-anchor" href="#private-contact" aria-label="Permalink to &quot;Private Contact&quot;">​</a></h3><p>Fill the home address with <strong>Street 1</strong>, <strong>Street 2</strong>, <strong>City</strong>, <strong>Postal Code</strong>, <strong>Country</strong> and <strong>State</strong>. The state list depends on the country. Then add <strong>Private Phone</strong>, <strong>Private Email</strong> and <strong>Private Car Plate</strong>.</p><p><strong><em>Distance Home to Work</em></strong> and <strong><em>Km Home to Work</em></strong> are numbers. <strong>Distance Unit</strong> switches between <strong>Kilometer</strong> and <strong>Meter</strong>.</p><p><strong><em>Bank Account:</em></strong> This field is greyed out on a new employee. It works only after the employee has a related user. See the Settings tab below.</p><h3 id="emergency-contact" tabindex="-1">Emergency Contact <a class="header-anchor" href="#emergency-contact" aria-label="Permalink to &quot;Emergency Contact&quot;">​</a></h3><ul><li><strong><em>Contact Name:</em></strong> Who to call.</li><li><strong><em>Contact Phone:</em></strong> Their number.</li></ul><h3 id="family-status" tabindex="-1">Family Status <a class="header-anchor" href="#family-status" aria-label="Permalink to &quot;Family Status&quot;">​</a></h3><p><strong><em>Marital Status:</em></strong> Defaults to <strong>Single</strong>. Choose <strong>Married</strong>, <strong>Divorced</strong> or <strong>Widowed</strong> and three more fields appear: <strong>Spouse Name</strong> (required), <strong>Spouse Birthday</strong> and <strong>Number of Children</strong>. With <strong>Single</strong> they stay hidden.</p><h3 id="education" tabindex="-1">Education <a class="header-anchor" href="#education" aria-label="Permalink to &quot;Education&quot;">​</a></h3><ul><li><strong><em>Certificate Level:</em></strong> <strong>Graduated</strong>, <strong>Bachelor</strong>, <strong>Master</strong>, <strong>Doctor</strong> or <strong>Other</strong>.</li><li><strong><em>Field of Study</em></strong> and <strong><em>School</em></strong>.</li></ul><h3 id="citizenship" tabindex="-1">Citizenship <a class="header-anchor" href="#citizenship" aria-label="Permalink to &quot;Citizenship&quot;">​</a></h3><p>Pick <strong>Country</strong> and <strong>State</strong>. <strong>State</strong> is required only when the country needs one. Then fill <strong>Identification ID</strong>, <strong>SSN No</strong>, <strong>SIN No</strong>, <strong>Passport ID</strong>, <strong>Gender</strong>, <strong>Date of Birth</strong> and <strong>Country of Birth</strong>.</p><h3 id="work-permit" tabindex="-1">Work Permit <a class="header-anchor" href="#work-permit" aria-label="Permalink to &quot;Work Permit&quot;">​</a></h3><p>Fill <strong>Visa Number</strong>, <strong>Work Permit No</strong>, <strong>Visa Expiration</strong> and <strong>Work Permit Expiration Date</strong>. Upload the document in <strong>Work Permit</strong>.</p><h2 id="tab-settings" tabindex="-1">Tab: Settings <a class="header-anchor" href="#tab-settings" aria-label="Permalink to &quot;Tab: Settings&quot;">​</a></h2><h3 id="employment-status" tabindex="-1">Employment Status <a class="header-anchor" href="#employment-status" aria-label="Permalink to &quot;Employment Status&quot;">​</a></h3><ul><li><strong><em>Active Employee:</em></strong> On by default. Turn it off when the person has left. See <a href="./leaving-the-company.html">Leaving the company</a>.</li><li><strong><em>Flexible Work Arrangement</em></strong> and <strong><em>Fully Flexible Schedule</em>:</strong> Off by default. Turn them on for staff with flexible hours. Leave them off if you do not use flexible hours.</li><li><strong><em>Work Permit Scheduled Activity:</em></strong> Off by default.</li><li><strong><em>Related User:</em></strong> The login of this employee. Users that already belong to another employee are greyed out. Click the plus button to create a user. The <strong>Create User</strong> window opens with <strong>Name</strong> and <strong>Email</strong> filled from the employee.</li><li><strong><em>Departure Reason:</em></strong> Leave empty for current staff.</li></ul><h3 id="additional-information" tabindex="-1">Additional Information <a class="header-anchor" href="#additional-information" aria-label="Permalink to &quot;Additional Information&quot;">​</a></h3><p><strong>Primary Language</strong>, <strong>Additional Notes</strong> and <strong>Notes</strong>.</p><h3 id="attendance-point-of-sale" tabindex="-1">Attendance/Point of Sale <a class="header-anchor" href="#attendance-point-of-sale" aria-label="Permalink to &quot;Attendance/Point of Sale&quot;">​</a></h3><ul><li><strong><em>Badge ID:</em></strong> Type a code, or click the plus button at the end to generate an 8 character code. It is saved only when you save the employee.</li><li><strong><em>PIN:</em></strong> A PIN code for this employee.</li></ul><h2 id="example-add-priya-sharma" tabindex="-1">Example: add Priya Sharma <a class="header-anchor" href="#example-add-priya-sharma" aria-label="Permalink to &quot;Example: add Priya Sharma&quot;">​</a></h2><p>Priya is the new Warehouse Supervisor in the Operations department.</p><ol><li>Open <code>Employees → Employees</code> and click <strong>New Employee</strong>.</li></ol>',44)),n(r,{src:"/images1/employees/emp_add_new_button.png",alt:"Employees list with the New Employee button outlined in orange"}),e[1]||(e[1]=a('<ol start="2"><li>In the top block, type <strong>Priya Sharma</strong> as <strong>Name</strong> and <strong>Warehouse Supervisor</strong> as <strong>Job Title</strong>.</li><li>Set <strong>Department</strong> to <strong>Operations</strong> and <strong>Job Position</strong> to <strong>Warehouse Supervisor</strong>.</li><li>Set <strong>Manager</strong> to <strong>Sarah Mitchell</strong> and <strong>Coach</strong> to <strong>Rachel Kim</strong>.</li><li>Pick the tags <strong>Operations</strong> and <strong>Senior</strong>.</li><li>Type <strong><a href="mailto:priya.sharma@mycompany.com" target="_blank" rel="noreferrer">priya.sharma@mycompany.com</a></strong> as <strong>Work Email</strong>, <strong>9876543210</strong> as <strong>Work Mobile</strong> and <strong>0221234567</strong> as <strong>Work Phone</strong>.</li></ol>',1)),n(r,{src:"/images1/employees/emp_add_top_block.png",alt:"Create Employees form with the top block filled for Priya Sharma"}),e[2]||(e[2]=a('<ol start="7"><li>Open the <strong>Work Information</strong> tab. Set <strong>Work Location</strong> to <strong>Building 1, Second Floor</strong> and <strong>Time Off</strong> to the user <strong>HR Admin</strong>. Leave <strong>Working Hours</strong> empty and keep <strong>Time Zone</strong> as <strong>UTC</strong>.</li></ol>',1)),n(r,{src:"/images1/employees/emp_add_work_tab.png",alt:"Work Information tab with work location Building 1 Second Floor and Time Off approver HR Admin filled"}),e[3]||(e[3]=a('<ol start="8"><li>Open the <strong>Private Information</strong> tab. Enter <strong>Pune</strong> as <strong>City</strong>, <strong>India</strong> as <strong>Country</strong> and <strong>9123456780</strong> as <strong>Private Phone</strong>. Keep <strong>Marital Status</strong> as <strong>Single</strong>.</li><li>Under <strong>Emergency Contact</strong>, enter <strong>Anil Sharma</strong> and <strong>9988776655</strong>.</li><li>Under <strong>Education</strong>, choose <strong>Bachelor</strong> and type <strong>Logistics</strong> as <strong>Field of Study</strong>.</li></ol>',1)),n(r,{src:"/images1/employees/emp_add_private_tab.png",alt:"Private Information tab with Pune, India, a private phone, emergency contact Anil Sharma and education Bachelor in Logistics filled"}),e[4]||(e[4]=t("ol",{start:"11"},[t("li",null,[o("Open the "),t("strong",null,"Settings"),o(" tab. Leave "),t("strong",null,"Active Employee"),o(" on.")])],-1)),n(r,{src:"/images1/employees/emp_add_settings_tab.png",alt:"Settings tab with Active Employee turned on"}),e[5]||(e[5]=t("ol",{start:"12"},[t("li",null,[o("Click "),t("strong",null,"Create"),o(". An "),t("strong",null,"Employee created"),o(" notification says "),t("strong",null,"The employee has been created successfully."),o(" Aureus opens the profile with the "),t("strong",null,"Resume"),o(" tab open. It is empty at first.")])],-1)),n(r,{src:"/images1/employees/emp_add_saved.png",alt:"Profile page of Priya Sharma with the Resume tab open, showing her resume lines and skill"}),e[6]||(e[6]=a('<h2 id="create-create-and-create-another-cancel" tabindex="-1">Create, Create and create another, Cancel <a class="header-anchor" href="#create-create-and-create-another-cancel" aria-label="Permalink to &quot;Create, Create and create another, Cancel&quot;">​</a></h2><ul><li><strong>Create:</strong> saves the employee and opens the profile page on the <strong>Resume</strong> tab.</li><li><strong>Create &amp; create another:</strong> saves and opens a blank form. Use it for batch entry.</li><li><strong>Cancel:</strong> leaves without saving.</li></ul><h2 id="behind-the-scenes" tabindex="-1">Behind the scenes <a class="header-anchor" href="#behind-the-scenes" aria-label="Permalink to &quot;Behind the scenes&quot;">​</a></h2><p>Each time you save an employee, Aureus creates a matching contact marked as an employee. It copies the name, work email, job title, phones, colour and company. If the contact exists, Aureus updates it on every save. See <a href="./../../../getting-started/contacts/contacts.html">Contacts</a>.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Related User needs a user to exist first. Create one in <a href="./../../../general-settings/users/manage-users.html">Manage users</a> or with the plus button.</p></div><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./employee-profile.html">Employee profile</a></li><li><a href="./skills-and-resume.html">Skills and resume</a></li><li><a href="./employee-list.html">Employee list</a></li><li><a href="./../departments/departments.html">Departments</a></li></ul>',7))])}const k=s(m,[["render",h]]);export{b as __pageData,k as default};
